pub fn transact(&mut self, expected: u64, edits: &[Edit], query: &Query) -> Outcome {
    if expected != self.revision {
        let cert = self.certificate(query);
        return Outcome { accepted: false, revision: self.revision, violations: None, certificate: cert };
    }
    self.tx_id += 1;
    let tx = self.tx_id;
    // pre-scan: snapshot tasks
    for e in edits { if let Some(t) = task_id(e) { if self.tx_stamp[t] != tx { self.tx_stamp[t] = tx; self.tx_snap[t] = Snap{...}; self.tx_f[t] = false } } }
    // mark groups
    self.tx_gmark.clear();
    for e in edits {
        match e {
            Quota(g, _) => self.mark_group(*g, tx),
            Move(t,_) | Weight(t,_) | Class(t,_) | Bind(t,_) => { let s = self.tx_snap[*t]; if s.pin && self.tx_gstamp[s.group] != tx { self.mark_group(s.group, tx) } }
            _ => {}
        }
    }
    self.tx_fcount = 0;
    // apply
    self.journal.clear(); self.journaling = true; self.tracking = true;
    for e in edits { let (c,i,v) = encode(e); self.apply(c,i,v); }
    self.tracking = false; self.journaling = false;
    // violations
    let mut pins = self.tx_fcount;
    for &g in &self.tx_gmark { if self.quota[g] != self.tx_gq0[g] { pins += self.tx_gclean[g] as usize } }
    let viol = [self.over_cap as u64, self.mixed as u64, self.work_bad as u64, pins as u64];
    let accepted = viol == [0,0,0,0];
    if accepted { self.revision += 1; self.journal.clear(); }
    else {
        let j = std::mem::take(&mut self.journal);
        for k in (0..j.len()).rev() { let (c,i,v) = j[k]; self.apply(c,i,v) }
        self.journal = j;   // reuse buffer
        debug_assert_eq!(self.over_cap, 0) etc.
    }
    let cert = self.certificate(query);
    Outcome { accepted, revision: self.revision, violations: Some(viol), certificate: cert }
}
```

