fn task_of(edit: &Edit) -> Option<usize> {
    match *edit {
        Edit::Move(id, _)
        | Edit::Weight(id, _)
        | Edit::Class(id, _)
        | Edit::Bind(id, _)
        | Edit::Pin(id, _) => Some(id),
