"""Independent reference implementation written straight from PROTOCOL.md."""
import json, sys
from collections import deque


def bfs_all(adj, n):
    out = []
    for s in range(n):
        d = [-1] * n
        d[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if d[v] < 0:
                    d[v] = d[u] + 1
                    q.append(v)
        out.append(d)
    return out


def build_topology(t):
    mode = t[0]
    if mode == 'clos':
        k, scope, intra = t[1], t[2], t[3]
        r = k // 2
        T = k * r
        n = k * k
        tpls = []
        for src in range(T):
            for dst in range(T):
                if src == dst:
                    continue
                if not intra and src // r == dst // r:
                    continue
                fp = {src, dst}
                for off in range(r):
                    fp.add(T + (src // r) * r + off)
                    fp.add(T + (dst // r) * r + off)
                dom = src if scope == 'tor' else src // r
                tpls.append((src, dst, frozenset(fp), dom))
        return n, tpls
    if mode == 'leaf-spine':
        leaves, spines = t[1], t[2]
        n = leaves + spines
        tpls = []
        for src in range(leaves):
            for dst in range(leaves):
                if src == dst:
                    continue
                tpls.append((src, dst, frozenset({src, dst}), src))
        return n, tpls
    if mode in ('torus2d', 'torus3d'):
        nn = t[1]
        scope = t[2]
        if mode == 'torus2d':
            n = nn * nn
            def nid(x, y): return y * nn + x
            dims = 2
        else:
            n = nn ** 3
            def nid(x, y, z): return (z * nn + y) * nn + x
            dims = 3
        adj = [[] for _ in range(n)]
        def coords(i):
            if dims == 2:
                return (i % nn, i // nn)
            return (i % nn, (i // nn) % nn, i // (nn * nn))
        def node(c):
            return nid(*c) if dims == 2 else nid(c[0], c[1], c[2])
        for i in range(n):
            c = list(coords(i))
            for ax in range(dims):
                for d in (1, -1):
                    c2 = list(c)
                    c2[ax] = (c2[ax] + d) % nn
                    j = node(tuple(c2))
                    adj[i].append(j)
        dist = bfs_all(adj, n)
        tpls = []
        for src in range(n):
            for dst in range(n):
                if src == dst:
                    continue
                dd = dist[src][dst]
                fp = frozenset(v for v in range(n)
                               if dist[src][v] >= 0 and dist[dst][v] >= 0
                               and dist[src][v] + dist[dst][v] == dd)
                if dims == 2:
                    dom = src if scope == 'host' else src // nn
                else:
                    dom = src if scope == 'host' else src // nn
                tpls.append((src, dst, fp, dom))
        return n, tpls
    if mode == 'dragonfly':
        g, a, h, scope = t[1], t[2], t[3], t[4]
        n = g * a
        adj = [[] for _ in range(n)]
        for grp in range(g):
            for i in range(a):
                for j in range(i + 1, a):
                    u, v = grp * a + i, grp * a + j
                    adj[u].append(v)
                    adj[v].append(u)
        for i in range(g):
            for j in range(i + 1, g):
                delta = j - i
                i1 = (delta - 1) // h
                i2 = (g - delta - 1) // h
                u, v = i * a + i1, j * a + i2
                adj[u].append(v)
                adj[v].append(u)
        dist = bfs_all(adj, n)
        tpls = []
        for src in range(n):
            for dst in range(n):
                if src == dst:
                    continue
                dd = dist[src][dst]
                fp = frozenset(v for v in range(n)
                               if dist[src][v] >= 0 and dist[dst][v] >= 0
                               and dist[src][v] + dist[dst][v] == dd)
                if scope == 'router':
                    dom = src
                elif scope == 'group':
                    dom = src // a
                else:
                    dom = src * g + dst // a
                tpls.append((src, dst, fp, dom))
        return n, tpls
    if mode == 'dragonfly-plus':
        g, l, s, h, dense, scope = t[1], t[2], t[3], t[4], t[5], t[6]
        sw = l + s
        n = g * sw
        adj = [[] for _ in range(n)]
        def leaf(grp, lf): return grp * sw + lf
        def spine(grp, sp): return grp * sw + l + sp
        for grp in range(g):
            for lf in range(l):
                for sp in range(s):
                    u, v = leaf(grp, lf), spine(grp, sp)
                    adj[u].append(v)
                    adj[v].append(u)
        if dense:
            for g1 in range(g):
                for g2 in range(g1 + 1, g):
                    for sp in range(s):
                        u, v = spine(g1, sp), spine(g2, sp)
                        adj[u].append(v)
                        adj[v].append(u)
        else:
            for g1 in range(g):
                for g2 in range(g1 + 1, g):
                    delta = g2 - g1
                    s1 = (delta - 1) // h
                    s2 = (g - delta - 1) // h
                    u, v = spine(g1, s1), spine(g2, s2)
                    adj[u].append(v)
                    adj[v].append(u)
        dist = bfs_all(adj, n)
        leaves = [leaf(grp, lf) for grp in range(g) for lf in range(l)]
        tpls = []
        for src in leaves:
            for dst in leaves:
                if src == dst:
                    continue
                dd = dist[src][dst]
                fp = frozenset(v for v in range(n)
                               if dist[src][v] >= 0 and dist[dst][v] >= 0
                               and dist[src][v] + dist[dst][v] == dd)
                if scope == 'group':
                    dom = src // sw
                else:
                    dom = (src // sw) * l + (src % sw)
                tpls.append((src, dst, fp, dom))
        return n, tpls
    raise ValueError('bad topology')


class Ref:
    def __init__(self, n, tpls, tasks, groups, caps):
        self.n = n
        self.tpls = tpls
        self.tasks = [list(x) for x in tasks]   # [tpl,group,weight,class,pin]
        self.quotas = [g[0] for g in groups]
        self.budgets = [g[1] for g in groups]
        self.caps = list(caps)
        self.revision = 0

    # ---- derived quantities of a full state -------------------------
    def derive(self, tasks, quotas, budgets, caps):
        G = len(quotas)
        n = self.n
        fp = [set() for _ in range(G)]
        load = [0] * G
        cnt = [0] * G
        pairs = [set() for _ in range(G)]
        for (tpl, g, w, c, p) in tasks:
            fp[g] |= self.tpls[tpl][2]
            load[g] += w
            cnt[g] += 1
            pairs[g].add((self.tpls[tpl][3], c))
        usage = [0] * n
        for g in range(G):
            if cnt[g] > 0:
                for v in fp[g]:
                    usage[v] += quotas[g]
        over = sum(1 for v in range(n) if usage[v] > caps[v])
        mixed = sum(1 for g in range(G) if len(pairs[g]) > 1)
        work = sum(1 for g in range(G)
                   if cnt[g] > 0 and (quotas[g] == 0 or load[g] > quotas[g] * budgets[g]))
        return dict(fp=fp, load=load, cnt=cnt, pairs=pairs, usage=usage,
                    over=over, mixed=mixed, work=work)

    def legal(self):
        d = self.derive(self.tasks, self.quotas, self.budgets, self.caps)
        return d['over'] == 0 and d['mixed'] == 0 and d['work'] == 0

    def certificate(self, query, d=None):
        if d is None:
            d = self.derive(self.tasks, self.quotas, self.budgets, self.caps)
        G = len(self.quotas)
        active = sum(1 for g in range(G) if d['cnt'][g] > 0)
        slots = sum(d['usage'])
        weight = sum(t[2] for t in self.tasks)
        pins = sum(1 for t in self.tasks if t[4])
        rows = []
        for g in query['groups']:
            if d['cnt'][g] > 0:
                pair = sorted(d['pairs'][g])[0]
                dom, cls = pair
            else:
                dom, cls = -1, -1
            rows.append([g, d['cnt'][g], d['load'][g], self.quotas[g], self.budgets[g],
                         len(d['fp'][g]), dom, cls])
        noder = [[v, d['usage'][v], self.caps[v]] for v in query['nodes']]
        taskr = [[t, self.tasks[t][1], self.tasks[t][0], self.tasks[t][2], self.tasks[t][3],
                  1 if self.tasks[t][4] else 0] for t in query['tasks']]
        return {"totals": [active, slots, weight, pins], "groups": rows,
                "nodes": noder, "tasks": taskr}

    def transact(self, tx, query):
        if tx['revision'] != self.revision:
            return {"accepted": False, "revision": self.revision, "violations": None,
                    "certificate": self.certificate(query)}
        # snapshot start state
        start_tasks = [list(x) for x in self.tasks]
        start_quotas = list(self.quotas)
        # proposal: apply edits in order
        tasks = [list(x) for x in self.tasks]
        quotas = list(self.quotas)
        budgets = list(self.budgets)
        caps = list(self.caps)
        for e in tx['edits']:
            op, idx, val = e
            if op == 'move':
                tasks[idx][1] = val
            elif op == 'weight':
                tasks[idx][2] = val
            elif op == 'class':
                tasks[idx][3] = val
            elif op == 'bind':
                tasks[idx][0] = val
            elif op == 'pin':
                tasks[idx][4] = 1 if val else 0
            elif op == 'quota':
                quotas[idx] = val
            elif op == 'budget':
                budgets[idx] = val
            elif op == 'cap':
                caps[idx] = val
            else:
                raise ValueError(op)
        d = self.derive(tasks, quotas, budgets, caps)
        pins = 0
        for t, st in enumerate(start_tasks):
            if not st[4]:
                continue
            g0 = st[1]
            if (tasks[t][1] != st[1] or tasks[t][0] != st[0] or tasks[t][2] != st[2]
                    or tasks[t][3] != st[3] or quotas[g0] != start_quotas[g0]):
                pins += 1
        viol = [d['over'], d['mixed'], d['work'], pins]
        accepted = all(v == 0 for v in viol)
        if accepted:
            self.tasks = tasks
            self.quotas = quotas
            self.budgets = budgets
            self.caps = caps
            self.revision += 1
        cert = self.certificate(query)
        return {"accepted": accepted, "revision": self.revision,
                "violations": viol, "certificate": cert}


def run(request):
    out = []
    for s in request['sessions']:
        n, tpls = build_topology(s['topology'])
        ref = Ref(n, tpls, s['tasks'], s['groups'], s['caps'])
        if not ref.legal():
            return {"error": "invalid"}
        init = ref.certificate(s['query'])
        txs = []
        for tx in s['transactions']:
            txs.append(ref.transact(tx, tx['query']))
        out.append({"nodes": n, "templates": len(tpls), "initial": init, "transactions": txs})
    return {"sessions": out}
